export interface AssetRecord {
  seq: number;
  kind: string;
  code: string;
  serial: string;
  region: string;
  slot: number;
  capacity: number;
  reserved: number;
  revision: number;
  tags?: string[];
  hostname?: string;
  volume_gb?: number;
}

export interface Manifest {
  regions: string[];
  assets: AssetRecord[];
}

export type Status = "inserted" | "rejected";

export interface ResultEntry {
  seq: number;
  kind: string;
  serial: string;
  status: Status;
  reason: string | null;
  error_class: string | null;
}

export interface SchemaReport {
  abstract_constraints: string[];
  delegated_pointer_constraints: string[];
  delegated_object_constraints: string[];
}

export interface Report {
  total: number;
  inserted: number;
  rejected: number;
  results: ResultEntry[];
  reason_counts: Record<string, number>;
  schema: SchemaReport;
}

import type { Client } from "gel";
import type { SchemaReport } from "./types";

interface AbstractConstraintRow {
  name: string;
}

interface DelegatedConstraintRow {
  ptr_name: string | null;
  ptr_type: string | null;
  obj_type: string | null;
}

function withoutModule(qualifiedName: string): string {
  const idx = qualifiedName.lastIndexOf("::");
  return idx === -1 ? qualifiedName : qualifiedName.slice(idx + 2);
}

/**
 * Performs live introspection of the database schema to discover:
 *  - every abstract constraint defined in module `default`
 *  - every pointer-level constraint marked `delegated` on a module `default` object type
 *  - every module `default` object type carrying a `delegated` object-level constraint
 *
 * Nothing here is hardcoded: all results are derived from querying the
 * `schema::Constraint` introspection type against the live database.
 */
export async function introspectSchema(client: Client): Promise<SchemaReport> {
  const abstractRows = await client.query<AbstractConstraintRow>(
    `select schema::Constraint { name }
     filter .abstract = true and .name like 'default::%';`,
  );
  const abstractConstraints = Array.from(
    new Set(abstractRows.map((r) => r.name)),
  ).sort();

  const delegatedRows = await client.query<DelegatedConstraintRow>(
    `select schema::Constraint {
       ptr_name := .subject[is schema::Pointer].name,
       ptr_type := .subject[is schema::Pointer].source[is schema::ObjectType].name,
       obj_type := .subject[is schema::ObjectType].name,
     }
     filter .delegated = true;`,
  );

  const pointerConstraints = new Set<string>();
  const objectConstraints = new Set<string>();

  for (const row of delegatedRows) {
    if (row.ptr_type && row.ptr_name && row.ptr_type.startsWith("default::")) {
      pointerConstraints.add(`${withoutModule(row.ptr_type)}.${row.ptr_name}`);
    }
    if (row.obj_type && row.obj_type.startsWith("default::")) {
      objectConstraints.add(withoutModule(row.obj_type));
    }
  }

  return {
    abstract_constraints: abstractConstraints,
    delegated_pointer_constraints: Array.from(pointerConstraints).sort(),
    delegated_object_constraints: Array.from(objectConstraints).sort(),
  };
}

import { type Client, ConstraintViolationError, MissingRequiredError } from "gel";
import type { AssetRecord, ResultEntry } from "./types";

const KIND_TO_TYPE: Record<string, string> = {
  server: "ServerAsset",
  storage: "StorageAsset",
};

interface FieldSpec {
  line: string;
  argName: string;
  value: unknown;
}

/**
 * Attempts to insert a single asset record against the live database.
 * The insert is issued as a single, standalone query so that a rejected
 * record leaves nothing behind (Gel implicitly wraps each top-level query
 * in its own transaction).
 */
export async function ingestAsset(
  client: Client,
  rec: AssetRecord,
): Promise<ResultEntry> {
  const base: Pick<ResultEntry, "seq" | "kind" | "serial"> = {
    seq: rec.seq,
    kind: rec.kind,
    serial: rec.serial,
  };

  const typeName = KIND_TO_TYPE[rec.kind];
  if (!typeName) {
    return {
      ...base,
      status: "rejected",
      reason: `UNKNOWN_KIND(${rec.kind})`,
      error_class: "InvalidValueError",
    };
  }

  const fields: FieldSpec[] = [
    { line: "code := <str>$code", argName: "code", value: rec.code },
    { line: "serial := <str>$serial", argName: "serial", value: rec.serial },
    {
      line: "region := (select Region filter .key = <str>$region_key)",
      argName: "region_key",
      value: rec.region,
    },
    { line: "slot := <int64>$slot", argName: "slot", value: rec.slot },
    {
      line: "capacity := <int64>$capacity",
      argName: "capacity",
      value: rec.capacity,
    },
    {
      line: "reserved := <int64>$reserved",
      argName: "reserved",
      value: rec.reserved,
    },
    {
      line: "revision := <int64>$revision",
      argName: "revision",
      value: rec.revision,
    },
  ];

  if (rec.tags !== undefined) {
    fields.push({
      line: "tags := array_unpack(<array<str>>$tags)",
      argName: "tags",
      value: rec.tags,
    });
  }

  if (rec.kind === "server") {
    if (rec.hostname !== undefined) {
      fields.push({
        line: "hostname := <str>$hostname",
        argName: "hostname",
        value: rec.hostname,
      });
    }
  } else if (rec.kind === "storage") {
    if (rec.volume_gb !== undefined) {
      fields.push({
        line: "volume_gb := <int64>$volume_gb",
        argName: "volume_gb",
        value: rec.volume_gb,
      });
    }
  }

  const args: Record<string, unknown> = {};
  for (const f of fields) args[f.argName] = f.value;

  const query = `select (insert ${typeName} {\n  ${fields
    .map((f) => f.line)
    .join(",\n  ")}\n}) { id };`;

  try {
    await client.query(query, args);
    return { ...base, status: "inserted", reason: null, error_class: null };
  } catch (err) {
    if (err instanceof ConstraintViolationError) {
      const reason = (err as unknown as { _message: string })._message;
      return {
        ...base,
        status: "rejected",
        reason,
        error_class: "ConstraintViolationError",
      };
    }
    if (err instanceof MissingRequiredError) {
      return {
        ...base,
        status: "rejected",
        reason: "MISSING_REQUIRED",
        error_class: "MissingRequiredError",
      };
    }
    throw err;
  }
}

import * as fs from "node:fs";
import { createClient } from "gel";
import type { Manifest, Report, ResultEntry } from "./types";
import { ingestAsset } from "./ingestAsset";
import { introspectSchema } from "./schemaIntrospect";

interface CliArgs {
  input: string;
  report: string;
}

function parseArgs(argv: string[]): CliArgs {
  let input: string | undefined;
  let report: string | undefined;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--input") {
      input = argv[++i];
    } else if (arg.startsWith("--input=")) {
      input = arg.slice("--input=".length);
    } else if (arg === "--report") {
      report = argv[++i];
    } else if (arg.startsWith("--report=")) {
      report = arg.slice("--report=".length);
    }
  }

  if (!input || !report) {
    throw new Error(
      "Both --input <manifest.json> and --report <report.json> flags are required",
    );
  }

  return { input, report };
}

function fail(message: string): never {
  process.stderr.write(`${message}\n`);
  process.exit(1);
}

async function main() {
  let args: CliArgs;
  try {
    args = parseArgs(process.argv.slice(2));
  } catch (err) {
    fail(err instanceof Error ? err.message : String(err));
  }

  let manifestText: string;
  try {
    manifestText = fs.readFileSync(args.input, "utf8");
  } catch (err) {
    fail(
      `Could not read manifest file '${args.input}': ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }

  let manifest: Manifest;
  try {
    manifest = JSON.parse(manifestText);
  } catch (err) {
    fail(
      `Could not parse manifest file '${args.input}' as JSON: ${
        err instanceof Error ? err.message : String(err)
      }`,
    );
  }

  if (
    !manifest ||
    typeof manifest !== "object" ||
    !Array.isArray(manifest.regions) ||
    !Array.isArray(manifest.assets)
  ) {
    fail(
      `Manifest file '${args.input}' must be an object with 'regions' and 'assets' arrays`,
    );
  }

  const client = createClient();

  try {
    for (const key of manifest.regions) {
      await client.query(
        `insert Region { key := <str>$key } unless conflict on .key else (select Region);`,
        { key },
      );
    }

    const sortedAssets = [...manifest.assets].sort((a, b) => a.seq - b.seq);

    const results: ResultEntry[] = [];
    const reasonCounts: Record<string, number> = {};
    let insertedCount = 0;
    let rejectedCount = 0;

    for (const rec of sortedAssets) {
      const outcome = await ingestAsset(client, rec);
      results.push(outcome);
      if (outcome.status === "inserted") {
        insertedCount++;
      } else {
        rejectedCount++;
        const reason = outcome.reason ?? "UNKNOWN";
        reasonCounts[reason] = (reasonCounts[reason] ?? 0) + 1;
      }
    }

    const schema = await introspectSchema(client);

    const report: Report = {
      total: sortedAssets.length,
      inserted: insertedCount,
      rejected: rejectedCount,
      results,
      reason_counts: reasonCounts,
      schema,
    };

    fs.writeFileSync(args.report, `${JSON.stringify(report, null, 2)}\n`, "utf8");

    console.log(`SUMMARY inserted=${insertedCount} rejected=${rejectedCount}`);
    process.exit(rejectedCount > 0 ? 2 : 0);
  } finally {
    await client.close();
  }
}

main().catch((err) => {
  process.stderr.write(`Unexpected error: ${err instanceof Error ? err.stack ?? err.message : String(err)}\n`);
  process.exit(1);
});

